package yagen.waitmydawn.mkb_export.client;
import yagen.waitmydawn.mkb_export.api.EntityAppearanceAdapter;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.phys.Vec3;
import com.google.gson.*;
import java.util.*;

final class AppearanceAdapters {
    private static final List<String> WARNINGS=new java.util.concurrent.CopyOnWriteArrayList<>();
    private static final Set<String> DISABLED=java.util.concurrent.ConcurrentHashMap.newKeySet();
    private static final List<EntityAppearanceAdapter> ADAPTERS=load();
    record Policy(boolean enabled,int parts,int variants,int millis) {}
    private static volatile Policy policy;
    static void freeze(){EntityVariants.clear();policy=new Policy(Platform.adaptersEnabled(),Platform.maxParts(),Platform.maxVariants(),Platform.adapterBudgetMillis());}
    static Policy policy(){var p=policy;if(p==null){freeze();p=policy;}return p;}
    static List<String> warnings(){return WARNINGS.stream().limit(128).map(s->s.substring(0,Math.min(2000,s.length()))).toList();}
    interface Operation<T>{T run()throws Exception;}
    static <T>T invoke(Operation<T> operation)throws Exception{long start=System.nanoTime();final T value;try{value=operation.run();}catch(LinkageError failure){throw new IllegalStateException("Appearance adapter linkage failure",failure);}if(System.nanoTime()-start>policy().millis()*1000000L)throw new IllegalArgumentException("Appearance adapter callback budget exceeded");return value;}
    private static List<EntityAppearanceAdapter> load(){
        var candidates=new ArrayList<EntityAppearanceAdapter>();candidates.add(new IceSpider());candidates.add(new Centipede());candidates.add(new VoidWorm());
        var providers=ServiceLoader.load(EntityAppearanceAdapter.class).stream().iterator();for(int count=0;count<128;count++){try{if(!providers.hasNext())break;var provider=providers.next();try{candidates.add(provider.get());}catch(java.util.ServiceConfigurationError|RuntimeException failure){WARNINGS.add("Provider initialization "+provider.type().getName()+": "+EntitySamples.describe(new IllegalStateException(failure)));}}catch(java.util.ServiceConfigurationError|RuntimeException failure){WARNINGS.add("Provider discovery: "+EntitySamples.describe(new IllegalStateException(failure)));break;}}
        var result=new ArrayList<EntityAppearanceAdapter>();var ids=new HashSet<String>();for(var a:candidates)try{if(!a.id().matches("[a-z0-9_.-]+:[a-z0-9_./-]+")||!ids.add(a.id())||a.version().isBlank()||a.version().length()>64)throw new IllegalArgumentException("Invalid adapter identity");result.add(a);}catch(RuntimeException|LinkageError failure){WARNINGS.add("Invalid provider: "+a.getClass().getName()+": "+EntitySamples.describe(new IllegalStateException(failure)));}
        for(String warning:WARNINGS)com.mojang.logging.LogUtils.getLogger().warn("MKB appearance adapter: {}",warning);return List.copyOf(result);
    }
    static EntityAppearanceAdapter find(String id){if(!policy().enabled())return null;EntityAppearanceAdapter found=null;for(var adapter:ADAPTERS){if(DISABLED.contains(adapter.id()))continue;boolean matched;try{matched=invoke(()->adapter.supports(id));}catch(Exception failure){if(DISABLED.add(adapter.id()))WARNINGS.add("Disabled predicate "+adapter.id()+": "+EntitySamples.describe(new IllegalStateException(failure)));continue;}if(matched){if(found!=null)throw new IllegalStateException("Conflicting adapters for "+id);found=adapter;}}return found;}
    static Entity rootOf(Entity hit)throws Exception {
        if(!policy().enabled())return hit;String id=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(hit.getType()).toString();EntityAppearanceAdapter selected=null;for(var a:ADAPTERS)if(!DISABLED.contains(a.id())&&invoke(()->a.supportsPart(id))){if(selected!=null)throw new IllegalArgumentException("Conflicting part adapters");selected=a;}if(selected==null)return hit;long start=System.nanoTime();var rootAdapter=selected;Entity root=invoke(()->rootAdapter.rootOf(hit));if(root==null||root.level()!=hit.level()||root.isRemoved()||System.nanoTime()-start>policy().millis()*1000000L)throw new IllegalArgumentException("Invalid part root");return root;
    }
    static JsonObject clientState(Entity source)throws Exception{String id=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(source.getType()).toString();var adapter=find(id);if(adapter==null)return new JsonObject();long start=System.nanoTime();var extra=invoke(()->adapter.captureClient(source));yagen.waitmydawn.mkb_export.core.AppearanceDataBudget.validate(extra);if(System.nanoTime()-start>policy().millis()*1000000L)throw new IllegalArgumentException("Client capture budget exceeded");var packet=new JsonObject();packet.addProperty("adapter",adapter.id());packet.addProperty("version",adapter.version());packet.add("state",extra.deepCopy());return packet;}
    static JsonArray vector(Vec3 value){var a=new JsonArray();a.add(value.x);a.add(value.y);a.add(value.z);return a;}
    static Vec3 vector(JsonElement node){var a=node.getAsJsonArray();var v=new Vec3(a.get(0).getAsDouble(),a.get(1).getAsDouble(),a.get(2).getAsDouble());if(!Double.isFinite(v.lengthSqr())||v.lengthSqr()<1e-12)throw new IllegalArgumentException("Invalid surface normal");return v.normalize();}
    private static class IceSpider implements EntityAppearanceAdapter {
        public String id(){return "mkb_export:ice_spider";}public String version(){return "1";}public boolean supports(String id){return id.equals("irons_spellbooks:ice_spider");}
        public Capture capture(Entity source,boolean observed)throws Exception {var extra=new JsonObject();boolean valid=true;for(String name:List.of("normal","lastNormal")){Vec3 v=(Vec3)source.getClass().getField(name).get(source);if(!Double.isFinite(v.lengthSqr())||v.lengthSqr()<1e-12){valid&=!observed;v=new Vec3(0,1,0);}extra.add(name,vector(v.normalize()));}var parts=new ArrayList<Part>();var standard=Platform.parts(source);for(int i=0;i<standard.length;i++)parts.add(new Part("collision_"+i,"root",standard[i],"PARENT_INCLUDED"));return new Capture(extra,parts,valid,valid?"":"Invalid observed surface normal; standing fallback");}
        public JsonObject captureClient(Entity source)throws Exception{var extra=new JsonObject();for(String name:List.of("normal","lastNormal")){Vec3 v=(Vec3)source.getClass().getField(name).get(source);if(Double.isFinite(v.lengthSqr())&&v.lengthSqr()>1e-12)extra.add(name,vector(v.normalize()));}return extra;}
        public void prepare(Entity copy,JsonObject extra,Map<String,Entity> nodes)throws Exception {if(extra.has("client")){var client=extra.getAsJsonObject("client");for(String name:List.of("normal","lastNormal"))if(client.has(name))extra.add(name,client.get(name));}for(String name:List.of("normal","lastNormal"))copy.getClass().getField(name).set(copy,vector(extra.get(name)));}
    }
    private static class Centipede implements EntityAppearanceAdapter {
        public String id(){return "mkb_export:alexsmobs_centipede";}public String version(){return "1";}public boolean supports(String id){return id.equals("alexsmobs:centipede_head");}
        public boolean supportsPart(String id){return id.equals("alexsmobs:centipede_body")||id.equals("alexsmobs:centipede_tail");}
        public Entity rootOf(Entity hit)throws Exception{var seen=Collections.newSetFromMap(new IdentityHashMap<Entity,Boolean>());for(int i=0;i<128;i++){if(!seen.add(hit))throw new IllegalArgumentException("Cyclic parent chain");String id=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.getKey(hit.getType()).toString();if(supports(id))return hit;Entity parent=(Entity)hit.getClass().getMethod("getParent").invoke(hit);if(parent==null)throw new IllegalArgumentException("Missing parent entity");hit=parent;}throw new IllegalArgumentException("Parent chain limit exceeded");}
        public Capture capture(Entity source,boolean observed)throws Exception {var parts=new ArrayList<Part>();var seen=Collections.newSetFromMap(new IdentityHashMap<Entity,Boolean>());seen.add(source);Entity cursor=source;String parent="root";int expected=((Number)source.getClass().getMethod("getSegmentCount").invoke(source)).intValue();for(int i=0;i<128;i++){Entity child=(Entity)cursor.getClass().getMethod("getChild").invoke(cursor);if(child==null)break;if(!seen.add(child))throw new IllegalArgumentException("Cyclic centipede chain");String key="segment_"+i;parts.add(new Part(key,parent,child,"INDEPENDENT"));parent=key;cursor=child;}boolean complete=parts.size()==expected&&expected>0;return new Capture(new JsonObject(),parts,complete,complete?"":"Expected "+expected+" segments; captured "+parts.size()+". Capture a live assembled entity.");}
    }
    private static class VoidWorm extends Centipede {
        public String id(){return "mkb_export:alexsmobs_void_worm";}public String version(){return "2";}public boolean supports(String id){return id.equals("alexsmobs:void_worm");}public boolean supportsPart(String id){return id.equals("alexsmobs:void_worm_part");}
        public Capture capture(Entity source,boolean observed)throws Exception {
            var captured=super.capture(source,observed);var parts=new ArrayList<Part>(captured.parts());var extra=new JsonObject();
            if(!observed&&parts.isEmpty()){
                int count=((Number)source.getClass().getMethod("getSegmentCount").invoke(source)).intValue();if(count<=0)count=20;if(count>AppearanceAdapters.policy().parts())throw new IllegalArgumentException("Void worm body count exceeds composition budget");
                String parent="root";for(int i=0;i<count;i++){var type=net.minecraft.core.registries.BuiltInRegistries.ENTITY_TYPE.get(Platform.location("alexsmobs","void_worm_part"));var part=type.create(source.level());if(part==null)throw new IllegalArgumentException("Void worm body factory missing");part.getClass().getMethod("setTail",boolean.class).invoke(part,i==count-1);part.getClass().getMethod("setWormScale",float.class).invoke(part,i==count-1?.75f:1f);double angle=i*.4,radius=2+i*.12;part.setPos(source.getX()+2-radius*Math.cos(angle),source.getY(),source.getZ()-1.8-radius*Math.sin(angle));float heading=(float)Math.toDegrees(Math.atan2(-.12*Math.cos(angle)+radius*.4*Math.sin(angle),.12*Math.sin(angle)+radius*.4*Math.cos(angle)));part.setYRot(heading);if(part instanceof net.minecraft.world.entity.LivingEntity living){living.yBodyRot=living.yBodyRotO=living.yHeadRot=living.yHeadRotO=heading;}setBodyYaw(part,heading);String key="segment_"+i;parts.add(new Part(key,parent,part,"INDEPENDENT"));parent=key;}extra.addProperty("presentation","STANDARD_ASSEMBLED");
            }
            var states=new JsonObject();float reference=source instanceof net.minecraft.world.entity.LivingEntity living?living.yBodyRot:source.getYRot();captureState(states,"root",source,reference);for(var part:parts)captureState(states,part.key(),part.entity(),reference);extra.add("nodes",states);
            boolean complete=!observed||captured.complete();return new Capture(extra,parts,complete,complete?"":"Void worm chain is incomplete; capture the assembled living entity");
        }
        private void captureState(JsonObject states,String key,Entity entity,float reference)throws Exception {var state=new JsonObject();for(String getter:List.of("getWormAngle","getWormScale","getPortalTicks"))try{Object value=entity.getClass().getMethod(getter).invoke(entity);if(value instanceof Number number){if(!Double.isFinite(number.doubleValue()))throw new IllegalArgumentException("Non-finite worm pose");state.addProperty(getter,number);}}catch(NoSuchMethodException absent){}try{float yaw=((Number)entity.getClass().getMethod("getWormYaw",float.class).invoke(entity,1f)).floatValue();if(!Float.isFinite(yaw))throw new IllegalArgumentException("Non-finite body yaw");state.addProperty("wormYaw",net.minecraft.util.Mth.wrapDegrees(yaw-reference));}catch(NoSuchMethodException absent){}states.add(key,state);}
        @SuppressWarnings("unchecked") private static void setBodyYaw(Entity entity,float yaw)throws Exception {
            var key=entity.getClass().getDeclaredField("WORM_YAW");key.setAccessible(true);entity.getEntityData().set((net.minecraft.network.syncher.EntityDataAccessor<Float>)key.get(null),yaw);var previous=entity.getClass().getDeclaredField("prevWormYaw");previous.setAccessible(true);previous.setFloat(entity,yaw);
        }
        public void prepare(Entity root,JsonObject extra,Map<String,Entity> nodes)throws Exception {
            for(var entry:nodes.entrySet()){var state=extra.getAsJsonObject("nodes").getAsJsonObject(entry.getKey());if(state==null)throw new IllegalArgumentException("Missing worm node pose");var entity=entry.getValue();if(state.has("wormYaw"))setBodyYaw(entity,state.get("wormYaw").getAsFloat());for(String name:List.of("WormAngle","WormScale","PortalTicks"))if(state.has("get"+name))try{var number=state.get("get"+name);var method=entity.getClass().getMethod("set"+name,name.equals("PortalTicks")?int.class:float.class);if(name.equals("PortalTicks"))method.invoke(entity,number.getAsInt());else method.invoke(entity,number.getAsFloat());}catch(NoSuchMethodException absent){}if(state.has("getWormAngle"))try{entity.getClass().getField("prevWormAngle").setFloat(entity,state.get("getWormAngle").getAsFloat());}catch(NoSuchFieldException absent){}}
        }
    }
}
